using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Security.Cryptography;using System.Threading.Tasks;using System.Windows.Forms;
namespace FssLauncher {
 public sealed class VerificationResult { public int Checked,Repaired,Limited;public readonly List<string> Problems=new List<string>();public override string ToString(){return Checked+" files checked; "+Repaired+" restored.\n"+(Problems.Count==0?"No problems found in the checks performed.":String.Join("\n",Problems.Take(12)))+"\n"+(Limited>0?Limited+" encrypted package indexes could not be checked.\n":"")+"Full file validation and repair require a supplied SHA256 manifest and matching repair copies.";}}
 public static class GameFileVerifier {
  static string Hash(string file){using(var sha=SHA256.Create())using(var stream=File.OpenRead(file))return BitConverter.ToString(sha.ComputeHash(stream)).Replace("-","").ToLowerInvariant();}
  static string Within(string root,string relative){string path=Path.GetFullPath(Path.Combine(root,relative.Replace('/',Path.DirectorySeparatorChar)));if(!path.StartsWith(Path.GetFullPath(root).TrimEnd('\\')+"\\",StringComparison.OrdinalIgnoreCase))throw new InvalidDataException("Manifest path escapes installation.");return path;}
  public static VerificationResult Verify(string executable,Action<int,string> progress){
   var result=new VerificationResult();string root=Path.GetFullPath(Path.Combine(Path.GetDirectoryName(executable),"../../.."));string manifest=Path.Combine(root,"FNClassic-files.sha256");
   if(File.Exists(manifest)){var rows=File.ReadAllLines(manifest).Where(line=>!String.IsNullOrWhiteSpace(line)&&!line.StartsWith("#")).ToArray();for(int n=0;n<rows.Length;n++){string row=rows[n];if(row.Length<67||row.Substring(64,2)!="  "||row.Substring(0,64).Any(c=>!Uri.IsHexDigit(c)))throw new InvalidDataException("Invalid SHA256 manifest.");string relative=row.Substring(66),expected=row.Substring(0,64).ToLowerInvariant(),file=Within(root,relative);if(progress!=null)progress((n+1)*60/Math.Max(1,rows.Length),"Verifying "+relative);bool valid=File.Exists(file)&&Hash(file)==expected;if(!valid){string repair=Within(Path.Combine(root,"FNClassic-repair"),relative);if(File.Exists(repair)&&Hash(repair)==expected){Directory.CreateDirectory(Path.GetDirectoryName(file));File.Copy(repair,file,true);result.Repaired++;valid=Hash(file)==expected;}if(!valid)result.Problems.Add(relative+": missing or corrupt; no verified repair copy available.");}result.Checked++;}}
   CoreStudio.FortniteBuilds.ValidateSupported(executable);result.Checked++;string directory=Path.Combine(root,"FortniteGame/Content/Paks");if(!Directory.Exists(directory)){result.Problems.Add("Missing FortniteGame/Content/Paks.");return result;}var files=Directory.GetFiles(directory,"*.pak");if(files.Length==0)result.Problems.Add("No game packages found.");for(int n=0;n<files.Length;n++){if(progress!=null)progress(60+(n+1)*40/Math.Max(1,files.Length),"Checking "+Path.GetFileName(files[n]));try{CheckPak(files[n],result);result.Checked++;}catch(Exception error){if(!(error is IOException)&&!(error is InvalidDataException))throw;result.Problems.Add(Path.GetFileName(files[n])+": "+error.Message);}}
   if(progress!=null)progress(100,"Verification finished");return result;
  }
  static void CheckPak(string path,VerificationResult result){using(var file=File.OpenRead(path))using(var reader=new BinaryReader(file)){int count=(int)Math.Min(file.Length,2048);file.Position=file.Length-count;byte[] tail=reader.ReadBytes(count);int footer=-1;long offset=0,length=0;int version=0;for(int i=count-44;i>=0;i--){if(BitConverter.ToUInt32(tail,i)!=0x5A6F12E1)continue;version=BitConverter.ToInt32(tail,i+4);offset=BitConverter.ToInt64(tail,i+8);length=BitConverter.ToInt64(tail,i+16);if(version>=1&&version<=9&&offset>=0&&length>0&&length<=268435456&&offset<=file.Length-length){footer=i;break;}}if(footer<0)throw new InvalidDataException("Package footer is missing or damaged.");if(version>=4&&footer>0&&tail[footer-1]!=0){result.Limited++;return;}file.Position=offset;byte[] data=reader.ReadBytes((int)length);using(var sha=SHA1.Create()){byte[] hash=sha.ComputeHash(data);for(int i=0;i<20;i++)if(hash[i]!=tail[footer+24+i])throw new InvalidDataException("Package index checksum mismatch.");}}}
 }
 public sealed partial class LauncherForm {
  bool verifying;
  async Task VerifyGameFiles(){if(verifying)return;if(connection.GameState=="Running"||connection.GameState=="Launching"){notice="Close Fortnite before verifying or restoring files.";Invalidate();return;}if(!File.Exists(gameExecutable)&&!await SelectGameBuild())return;verifying=true;ModeButton.Enabled=false;ApplyState();try{var result=await Task.Run(delegate{return GameFileVerifier.Verify(gameExecutable,delegate(int percent,string message){if(!IsDisposed)BeginInvoke(new Action(delegate{notice="Verifying "+percent+"% — "+message;Invalidate();}));});});notice=result.ToString();MessageBox.Show(this,notice,"Verify Game Files",MessageBoxButtons.OK,result.Problems.Count==0?MessageBoxIcon.Information:MessageBoxIcon.Warning);}catch(Exception error){notice="Verification failed: "+error.Message;MessageBox.Show(this,notice,"Verify Game Files",MessageBoxButtons.OK,MessageBoxIcon.Error);}finally{verifying=false;ModeButton.Enabled=true;ApplyState();}}
 }
}
